import statistics


def summarise(readings):
    """An hour of careful work that was never committed."""
    return {
        'mean': statistics.mean(readings),
        'median': statistics.median(readings),
        'stdev': statistics.stdev(readings) if len(readings) > 1 else 0.0,
        'range': max(readings) - min(readings),
    }
